<?php
defined('ABSPATH') || exit;

/** Independent facets; SQL closure joins never load the question corpus into PHP. */
final class CAFCC_Facets {
    public static function init(){add_action('rest_api_init',array(__CLASS__,'routes'));add_action('admin_menu',function(){if(CAFCC_Repository::admin_allowed())add_submenu_page('cafcc','Academic search aliases','Academic search aliases','manage_options','cafcc-aliases',array(__CLASS__,'screen'));});add_action('admin_post_cafcc_alias',function(){if(!CAFCC_Repository::admin_allowed()||!isset($_POST['_wpnonce'])||!is_string($_POST['_wpnonce'])||!wp_verify_nonce(wp_unslash($_POST['_wpnonce']),'cafcc_alias'))wp_die('Secure administrator request required.','',array('response'=>403));$r=self::alias(array('node_id'=>$_POST['node_id']??null,'alias_text'=>isset($_POST['alias_text'])&&is_string($_POST['alias_text'])?wp_unslash($_POST['alias_text']):'','reviewed'=>isset($_POST['reviewed'])));if(is_wp_error($r))wp_die(esc_html($r->get_error_message()));wp_safe_redirect(admin_url('admin.php?page=cafcc-aliases'));exit;});}
    public static function filters($r){
        $subject=CAFCC_Repository::id($r->get_param('subject_id'),true);if(is_wp_error($subject))return $subject;$sr=$subject?CAFCC_Repository::get('subjects',$subject):null;$ibs=$sr&&$sr['code']==='IBS';if($subject&&!$sr)return CAFCC_Repository::error('Subject unavailable.');
        $base=clone $r;foreach(array('chapter_id','unit_id','topic_id','subtopic_id') as $key)$base->set_param($key,null);if($ibs)$base->set_param('subject_id',null);
        $f=CAFCC_Explorer::filters($base);if(is_wp_error($f))return $f;$f['subject_id']=$subject;
        $status=$r->get_param('practice_status')??'';if(!is_string($status)||($status&&!in_array($status,CAFCC_Repository::STATUSES,true)))return CAFCC_Repository::error('Invalid practice status.');$f['practice_status']=$status;$personal=$r->get_param('personal')??'';if(!is_string($personal)||!in_array($personal,array('','all','bookmarks','needs_revision','important','difficult','notes','highlighted','recent'),true))return CAFCC_Repository::error('Invalid personal practice view.');$f['personal']=$personal;$tag=$r->get_param('private_tag')??'';if(!is_string($tag)||strlen($tag)>60)return CAFCC_Repository::error('Invalid private tag filter.');$f['private_tag']=sanitize_text_field($tag);$f['node_ids']=array();
        foreach(array('chapter','unit','topic','subtopic') as $type){$key=$type.'_id';$id=CAFCC_Repository::id($r->get_param($key),true);if(is_wp_error($id))return $id;$f[$key]=$id;if(!$id)continue;$n=CAFCC_Academic::get('taxonomy',$id);
            if(!$n||$n['node_type']!==$type||!CAFCC_Academic::path_published($id)||(!$ibs&&$subject&&(int)$n['subject_id']!==$subject)||($f['edition_id']&&(int)$n['edition_id']!==$f['edition_id']))return CAFCC_Repository::error('The selected concept is unavailable or has conflicting subject/edition context.');$f['node_ids'][]=$id;
        }return $f;
    }
    public static function parts($f,$uid){
        global $wpdb;
        $base=$f;foreach(array('chapter_id','unit_id','topic_id','subtopic_id') as $k)$base[$k]=null;$base['search']='';
        list($from,$where,$args)=CAFCC_Explorer::query_parts($base,$uid);
        if(!empty($f['practice_status'])){$where.=" AND COALESCE(p.status,'not_started')=%s";$args[]=$f['practice_status'];}
        if(!empty($f['personal'])){$nb=CAFCC_Practice::table('notebook');$pr=CAFCC_DB::table('progress');$st=CAFCC_Study::table('personal');$ss=CAFCC_Study::table('sessions');$sh=CAFCC_Study::table('highlights');$mode=$f['personal'];
            if($mode==='needs_revision'){$where.=" AND (p.status='needs_revision' OR EXISTS(SELECT 1 FROM $st x WHERE x.user_id=%d AND x.question_id=q.id AND x.outcome='needs_revision'))";$args[]=$uid;}
            elseif(in_array($mode,array('important','difficult'),true)){$where.=" AND EXISTS(SELECT 1 FROM $st x WHERE x.user_id=%d AND x.question_id=q.id AND JSON_CONTAINS(x.tags_json,JSON_QUOTE(%s)))";array_push($args,$uid,ucfirst($mode));}
            elseif($mode==='highlighted'){$where.=" AND EXISTS(SELECT 1 FROM $sh x WHERE x.user_id=%d AND x.question_id=q.id)";$args[]=$uid;}
            elseif($mode==='recent'){$where.=" AND EXISTS(SELECT 1 FROM $ss x WHERE x.user_id=%d AND x.question_id=q.id)";$args[]=$uid;}
            else{$condition=$mode==='bookmarks'?"np.bookmarked=1":($mode==='notes'?"np.note_text<>''":"(np.bookmarked=1 OR np.note_text<>'')");$where.=" AND (EXISTS(SELECT 1 FROM $nb np WHERE np.question_id=q.id AND np.user_id=%d AND $condition)";$args[]=$uid;if($mode==='all'){$where.=" OR EXISTS(SELECT 1 FROM $pr pp WHERE pp.question_id=q.id AND pp.user_id=%d) OR EXISTS(SELECT 1 FROM $st x WHERE x.question_id=q.id AND x.user_id=%d) OR EXISTS(SELECT 1 FROM $sh h WHERE h.question_id=q.id AND h.user_id=%d)";array_push($args,$uid,$uid,$uid);}$where.=')';}}
        if(!empty($f['private_tag'])){$private=CAFCC_Study::table('personal');$where.=" AND EXISTS(SELECT 1 FROM $private private_tag WHERE private_tag.question_id=q.id AND private_tag.user_id=%d AND JSON_CONTAINS(private_tag.tags_json,JSON_QUOTE(%s)))";array_push($args,$uid,$f['private_tag']);}
        $t=CAFCC_DB::table('question_tags');$n=CAFCC_DB::table('taxonomy');$cl=CAFCC_Bank_DB::table('closure');$aliases=CAFCC_Bank_DB::table('aliases');
        foreach($f['node_ids']??array() as $id){$where.=" AND EXISTS (SELECT 1 FROM $t bt JOIN $cl bc ON bc.descendant_id=bt.node_id JOIN $n bn ON bn.id=bt.node_id WHERE bt.question_id=q.id AND bc.ancestor_id=%d AND ".CAFCC_Academic::published('bt')." AND ".CAFCC_Owner::usable_sql('bn').")";$args[]=$id;}
        if(!empty($f['search'])){if(CAFCC_Search_Tags::standard_query($f['search'])){$where.=' AND '.CAFCC_Search_Tags::search_sql('q.id',$f['search'],$args);}else{$like='%'.$wpdb->esc_like($f['search']).'%';$content=CAFCC_Practice::table('content');
            $rt=CAFCC_Studio::table();$tagargs=array();$tagsql=CAFCC_Search_Tags::search_sql('q.id',$f['search'],$tagargs);$where.=" AND (EXISTS(SELECT 1 FROM $rt public_id WHERE public_id.question_id=q.id AND public_id.publication_status='published' AND public_id.status='approved' AND public_id.question_format='subjective' AND public_id.stable_id LIKE %s) OR q.title LIKE %s OR q.question_number LIKE %s OR qm.stable_key LIKE %s OR EXISTS (SELECT 1 FROM $content pc WHERE pc.question_id=q.id AND pc.content_kind='question' AND ".CAFCC_Practice::permitted_sql('pc')." AND pc.search_text LIKE %s) OR EXISTS (SELECT 1 FROM $t st JOIN $cl sc ON sc.descendant_id=st.node_id JOIN $n sn ON sn.id=sc.ancestor_id WHERE st.question_id=q.id AND ".CAFCC_Academic::published('st')." AND ".CAFCC_Owner::usable_sql('sn')." AND (sn.title LIKE %s OR EXISTS(SELECT 1 FROM $aliases sa WHERE sa.node_id=sn.id AND sa.review_status='verified' AND sa.alias_text LIKE %s))) OR $tagsql)";
            array_push($args,$like,$like,$like,$like,$like,$like,$like);array_push($args,...$tagargs);}
        }return array($from,$where,$args);
    }
    public static function node_search($r){
        global $wpdb;$f=self::filters($r);if(is_wp_error($f))return $f;
        $term=$r->get_param('term')??'';$type=$r->get_param('type')??'';
        if(!is_string($term)||strlen($term)>120 || !is_string($type)||($type&&!in_array($type,CAFCC_Academic::NODE_TYPES,true)))return CAFCC_Repository::error('Invalid concept search.');
        $parents=$f;$f['search']='';$f['node_ids']=array();foreach(array('chapter_id','unit_id','topic_id','subtopic_id') as $k)$f[$k]=null;
        list($from,$where,$args)=self::parts($f,get_current_user_id());
        $n=CAFCC_DB::table('taxonomy');$e=CAFCC_DB::table('editions');$s=CAFCC_DB::table('subjects');$t=CAFCC_DB::table('question_tags');$cl=CAFCC_Bank_DB::table('closure');$a=CAFCC_Bank_DB::table('aliases');
        $sql="SELECT n.id,n.title,n.node_type,n.edition_id,n.subject_id,n.parent_id,n.heading_origin,e.title AS edition_title,s.code AS subject_code FROM $n n JOIN $e e ON e.id=n.edition_id JOIN $s s ON s.id=n.subject_id WHERE ".CAFCC_Owner::usable_sql('n')." AND ".CAFCC_Owner::usable_sql('e');$na=array();
        if($term){$sql.=" AND (n.title LIKE %s OR EXISTS(SELECT 1 FROM $a a WHERE a.node_id=n.id AND a.review_status='verified' AND a.alias_text LIKE %s))";$like='%'.$wpdb->esc_like($term).'%';array_push($na,$like,$like);}
        if($type){$sql.=' AND n.node_type=%s';$na[]=$type;}
        if($f['subject_id']&&CAFCC_Repository::get('subjects',$f['subject_id'])['code']!=='IBS'){$sql.=' AND n.subject_id=%d';$na[]=$f['subject_id'];}if($f['edition_id']){$sql.=' AND n.edition_id=%d';$na[]=$f['edition_id'];}
        $levels=array('chapter'=>0,'unit'=>1,'topic'=>2,'subtopic'=>3);if(isset($levels[$type]))foreach($levels as $parent_type=>$level){$pid=$parents[$parent_type.'_id']??null;if($pid&&$level<$levels[$type]){$sql.=" AND EXISTS(SELECT 1 FROM $cl dependency WHERE dependency.ancestor_id=%d AND dependency.descendant_id=n.id)";$na[]=$pid;}}
        $scope=$r->get_param('scope')??'browse';if(!is_string($scope)||!in_array($scope,array('browse','practice'),true))return CAFCC_Repository::error('Choose Browse Syllabus or Practice Questions.');
        // Filter every ancestor before LIMIT, so drafts cannot leak or crowd out valid paths.
        $sql.=" AND NOT EXISTS(SELECT 1 FROM $cl ac JOIN $n an ON an.id=ac.ancestor_id WHERE ac.descendant_id=n.id AND NOT (".CAFCC_Owner::usable_sql('an')."))";
        $qt=CAFCC_DB::table('questions');$tail=substr($from,strlen("FROM $qt q"));$availability="SELECT DISTINCT nc.ancestor_id FROM $cl nc STRAIGHT_JOIN $t nt ON nt.node_id=nc.descendant_id STRAIGHT_JOIN $qt q ON q.id=nt.question_id $tail WHERE $where AND ".CAFCC_Academic::published('nt');
        if($scope==='practice'){$candidate_sql=preg_replace('/^SELECT .*? FROM /s','SELECT n.id FROM ',$sql,1);$availability.=" AND nc.ancestor_id IN ($candidate_sql)";$candidate_args=$na;$join_at=strpos($sql,' WHERE ');$sql=substr($sql,0,$join_at)." JOIN ($availability) available_nodes ON available_nodes.ancestor_id=n.id".substr($sql,$join_at);$na=array_merge($args,$candidate_args,$na);}
        $sql.=' ORDER BY n.position,n.id LIMIT 31';
        $rows=$wpdb->get_results($na?$wpdb->prepare($sql,$na):$sql,ARRAY_A);if(!is_array($rows))return CAFCC_Repository::error('Academic search is temporarily unavailable.',503);$more=count($rows)>30;$rows=array_slice($rows,0,30);$available=array();
        if($rows&&$scope==='browse'){$ids=array_map('intval',array_column($rows,'id'));$placeholders=implode(',',array_fill(0,count($ids),'%d'));$available=array_map('intval',$wpdb->get_col($wpdb->prepare($availability.' AND nc.ancestor_id IN ('.$placeholders.')',array_merge($args,$ids))));}
        foreach($rows as &$node)$node['has_questions']=$scope==='practice'||in_array((int)$node['id'],$available,true);unset($node);
        foreach($rows as &$node){$node['has_questions']=(bool)$node['has_questions'];$node['ancestors']=self::context((int)$node['id']);}
        $tag_suggestions=array();if($term&&!$type){$terms=CAFCC_Search_Tags::table();$editions=CAFCC_DB::table('editions');$ta=$args;$term_predicate=CAFCC_Search_Tags::predicate('academic_term',$term,$ta);$tag_suggestions=$wpdb->get_results($wpdb->prepare("SELECT DISTINCT academic_term.label,academic_term.kind,s.code AS subject_code,s.id AS subject_id,qm.edition_id,te.title AS edition_title $from JOIN $terms academic_term ON academic_term.question_id=q.id JOIN $editions te ON te.id=qm.edition_id WHERE $where AND $term_predicate ORDER BY academic_term.label LIMIT 10",$ta),ARRAY_A);}return array('tag_suggestions'=>$tag_suggestions,'items'=>$rows,'more'=>$more,'scope'=>$scope,'availability'=>$scope==='browse'?'Available source-backed or owner-authorised provisional paths; questions may not yet be available.':'Reviewed paths with eligible published questions.');
    }
    public static function context($id){$node=CAFCC_Academic::get('taxonomy',$id);$path=array();if(!$node)return $path;foreach(array_reverse(CAFCC_Explorer::ancestors($node)) as $nid){$r=CAFCC_Academic::get('taxonomy',$nid);$path[]=array('id'=>(int)$nid,'type'=>$r['node_type'],'title'=>$r['title']);}return $path;}
    public static function questions($r){
        global $wpdb;$f=self::filters($r);if(is_wp_error($f))return $f;
        list($from,$where,$args)=self::parts($f,get_current_user_id());$o=CAFCC_DB::table('occurrences');$od=CAFCC_DB::table('documents');$dm=CAFCC_DB::table('document_meta');
        $from.=" JOIN $o bo ON bo.question_id=q.id JOIN $od bd ON bd.id=bo.document_id JOIN $dm bm ON bm.document_id=bd.id";
        $where.=' AND '.CAFCC_Academic::published('bo').' AND '.CAFCC_Academic::published('bm')." AND bd.verification_status='verified'";
        if(class_exists('CAFCC_Studio'))$where.=CAFCC_Studio::occurrence_guard('bo');
        foreach(array('source_type','exam_attempt','mtp_series') as $key){if(!empty($f[$key])){$where.=" AND ".($key==='mtp_series'?'bm':'bd').".$key=%s";$args[]=$f[$key];}}
        $total=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) $from WHERE $where",$args));$qa=$args;array_push($qa,20,($f['page']-1)*20);
        $rows=$wpdb->get_results($wpdb->prepare("SELECT q.id,q.title,q.question_number,c.title AS chapter_title,c.syllabus_version,s.code AS subject_code,qm.edition_id,qm.stable_key,qm.question_type,bo.id AS occurrence_id,COALESCE(p.status,'not_started') AS progress_status $from WHERE $where ORDER BY bo.id DESC LIMIT %d OFFSET %d",$qa),ARRAY_A);
        foreach($rows as &$q){$q['occurrences']=array_values(array_filter(CAFCC_Explorer::occurrences($q['id']),function($o)use($q){return (int)$o['id']===(int)$q['occurrence_id'];}));$q['classifications']=CAFCC_Explorer::tags($q['id']);$q['practice_content']=class_exists('CAFCC_Studio')?CAFCC_Studio::occurrence_content((int)$q['id'],(int)$q['occurrence_id'],'question'):CAFCC_Practice::public_content((int)$q['id'],'question');$q['notebook']=CAFCC_Practice::notebook((int)$q['id']);$q['legacy_reference']=false;if(class_exists('CAFCC_Studio')){$rt=CAFCC_Studio::table();$context=$wpdb->get_var($wpdb->prepare("SELECT JSON_EXTRACT(payload,'$.classification_context') FROM $rt WHERE occurrence_id=%d AND publication_status='published'",$q['occurrence_id']));$q['primary_classification']=json_decode($context?:'{}',true);$q['source_citations']=array();foreach($q['occurrences'] as $occ){$title=$q['primary_classification']['topic']['title']??$q['primary_classification']['chapter']['title']??$q['chapter_title'];$standard='';if(preg_match('/Ind\s+AS\s*\d+/i',$q['primary_classification']['chapter']['title']??$q['chapter_title'],$m))$standard=$m[0];if($standard)$title=$standard;$label=implode(' · ',array_filter(array(strtoupper($occ['source_type']),$q['subject_code'],$occ['exam_attempt'],$occ['mtp_series']?'Series '.$occ['mtp_series']:'','Q'.$occ['question_number'].($occ['subquestion_number']?'('.$occ['subquestion_number'].')':''),$title)));$q['source_citations'][]=array('occurrence_id'=>(int)$occ['id'],'label'=>$label,'url'=>$occ['official_url'],'page'=>$occ['page_reference'],'hosting_label'=>CAFCC_Sources::hosting($occ['official_url']),'authored'=>$occ['source_type']==='other'&&($q['practice_content']['rights_label']??'')==='Independently authored');}if(!empty($q['primary_classification']['chapter']['title']))$q['chapter_title']=$q['primary_classification']['chapter']['title'];}}
        foreach($rows as &$card){$rt=CAFCC_Studio::table();$rr=$wpdb->get_row($wpdb->prepare("SELECT id,owner_publication,owner_answer_state FROM $rt WHERE occurrence_id=%d AND publication_status='published'",$card['occurrence_id']),ARRAY_A);$card['academic_tags']=$rr?CAFCC_Search_Tags::for_review($rr['id']):array();$card['academic_status']=($rr['owner_publication']??'')==='provisional'?'Owner-authorised · Academic verification pending':'Owner-reviewed publication';$card['answer_status']=$rr['owner_answer_state']??'available';}return array('items'=>$rows,'total'=>$total,'per_page'=>20,'page'=>$f['page']);
    }
    public static function summary($r){
        global $wpdb;$f=self::filters($r);if(is_wp_error($f))return $f;list($from,$where,$args)=self::parts($f,get_current_user_id());
        $rows=$wpdb->get_results($wpdb->prepare("SELECT COALESCE(p.status,'not_started') AS status,COUNT(*) AS count $from WHERE $where GROUP BY COALESCE(p.status,'not_started')",$args),ARRAY_A);
        $counts=array_fill_keys(CAFCC_Repository::STATUSES,0);foreach($rows as $row)$counts[$row['status']]=(int)$row['count'];return array('counts'=>$counts,'total'=>array_sum($counts));
    }
    public static function catalog($r){
        global $wpdb;$f=self::filters($r);if(is_wp_error($f))return $f;
        $s=CAFCC_DB::table('subjects');$e=CAFCC_DB::table('editions');$d=CAFCC_DB::table('documents');
        $ed=$wpdb->get_results("SELECT id,title,subject_id,applicability FROM $e e WHERE ".CAFCC_Owner::usable_sql('e')." ORDER BY id",ARRAY_A);
        $bf=$f;$bf['source_type']='';$bf['exam_attempt']='';$bf['search']='';$bf['node_ids']=array();
        list($from,$where,$args)=self::parts($bf,get_current_user_id());$o=CAFCC_DB::table('occurrences');$dm=CAFCC_DB::table('document_meta');
        $choices=$wpdb->get_results($wpdb->prepare("SELECT DISTINCT fd.source_type,fd.exam_attempt $from JOIN $o fo ON fo.question_id=q.id JOIN $d fd ON fd.id=fo.document_id JOIN $dm fm ON fm.document_id=fd.id WHERE $where AND ".CAFCC_Academic::published('fo')." AND ".CAFCC_Academic::published('fm')." AND fd.verification_status='verified' ORDER BY fd.exam_attempt DESC",$args),ARRAY_A);
        $dm=CAFCC_DB::table('document_meta');$all_sources=$wpdb->get_results("SELECT DISTINCT d.source_type,d.exam_attempt,dm.scheme,dm.mtp_series,d.title,d.official_url FROM $d d JOIN $dm dm ON dm.document_id=d.id WHERE d.verification_status='verified' AND dm.review_status='verified' AND d.official_url<>'' ORDER BY d.exam_attempt DESC",ARRAY_A);$attempts=array_values(array_unique(array_filter(array_column($all_sources,'exam_attempt'))));$published=array_values(array_unique(array_column($choices,'exam_attempt')));$attempt_meta=array();foreach($attempts as $value)$attempt_meta[]=array('value'=>$value,'has_questions'=>in_array($value,$published,true),'context'=>'Verified source metadata; RTP target, MTP target/series and actual exam identities remain distinct in each citation.');
        return array('attempt_metadata'=>$attempt_meta,'published_subjective_attempts'=>$published,'verified_sources'=>$all_sources,'subjects'=>$wpdb->get_results("SELECT id,code,name FROM $s ORDER BY id",ARRAY_A),'editions'=>$ed,'source_types'=>array_values(array_unique(array_column($all_sources,'source_type'))),'exam_attempts'=>$attempts);
    }
    public static function alias($data){
        if(!CAFCC_Repository::admin_allowed())return CAFCC_Repository::error('Administrator access required.',403);
        $id=CAFCC_Repository::id($data['node_id']??null);$text=$data['alias_text']??'';
        if(is_wp_error($id)||!CAFCC_Academic::get('taxonomy',$id)||!is_string($text)||!trim($text)||strlen($text)>190)return CAFCC_Repository::error('Choose an existing node and a short alias.');
        global $wpdb;$row=array('node_id'=>$id,'alias_text'=>sanitize_text_field($text),'review_status'=>true===($data['reviewed']??false)?'verified':'needs_review');
        return CAFCC_Academic::transaction(function()use($row){global $wpdb;$t=CAFCC_Bank_DB::table('aliases');$before=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE node_id=%d AND alias_text=%s FOR UPDATE",$row['node_id'],$row['alias_text']),ARRAY_A);if(false===($before?$wpdb->update($t,$row,array('id'=>$before['id'])):$wpdb->insert($t,$row)))return CAFCC_Repository::error('Cannot save alias.',500);$id=$before?$before['id']:$wpdb->insert_id;if(!CAFCC_Bank_DB::audit_master('aliases',$id,$before,$row))return CAFCC_Repository::error('Cannot retain alias audit.',500);return array_merge($row,array('id'=>$id));});
    }
    public static function screen(){
        if(!CAFCC_Repository::admin_allowed())wp_die('Administrator access required.');global $wpdb;$t=CAFCC_DB::table('taxonomy');$term=isset($_GET['term'])&&is_string($_GET['term'])?sanitize_text_field(wp_unslash($_GET['term'])):'';$rows=$wpdb->get_results($wpdb->prepare("SELECT id,title,node_type,edition_id,heading_origin,review_status FROM $t WHERE title LIKE %s ORDER BY id DESC LIMIT 50",'%'.$wpdb->esc_like($term).'%'),ARRAY_A);
        echo '<div class="wrap"><h1>Academic search aliases</h1><p>Aliases are student search terms, not new official ICAI headings. Review taxonomy in the Connected academic manager first. New aliases start unreviewed unless you explicitly confirm them.</p><form method="get"><input type="hidden" name="page" value="cafcc-aliases"><label>Find an academic node <input name="term" value="'.esc_attr($term).'"></label><button class="button">Find</button></form><table class="widefat"><thead><tr><th>ID</th><th>Title</th><th>Edition</th><th>Origin / status</th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.esc_html($r['id']).'</td><td>'.esc_html($r['title']).'</td><td>'.esc_html($r['edition_id']).'</td><td>'.esc_html($r['heading_origin'].' / '.$r['review_status']).'</td></tr>';echo '</tbody></table><h2>Add or re-review an alias</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field('cafcc_alias','_wpnonce',true,false).'<input type="hidden" name="action" value="cafcc_alias"><p><label>Node ID <input name="node_id" type="number" min="1" required></label></p><p><label>Search alias <input name="alias_text" maxlength="190" placeholder="For example: IndAS115" required></label></p><label><input type="checkbox" name="reviewed"> I reviewed this alias and its exact edition/node mapping.</label><p><button class="button button-primary">Save alias</button></p></form><p>Browse Syllabus includes reviewed paths even when no questions are available. Practice Questions remains restricted to eligible published occurrences. An alias never approves a draft path or question.</p></div>';
    }
    public static function routes(){
        register_rest_route('cafcc/v4','/answers/(?P<id>[1-9][0-9]{0,17})',array('methods'=>'GET','permission_callback'=>function($r){return CAFCC_REST::permission($r);},'callback'=>function($r){return class_exists('CAFCC_Studio')?CAFCC_Studio::answers((int)$r['id'],(int)$r->get_param('occurrence_id')):CAFCC_Explorer::answers((int)$r['id']);}));
        $student=function($r){return CAFCC_REST::permission($r);};$admin=function($r){return CAFCC_REST::permission($r,true);};
        foreach(array('questions','catalog','node_search','summary') as $method)register_rest_route('cafcc/v4','/'.('node_search'===$method?'concepts':$method),array('methods'=>'GET','permission_callback'=>$student,'callback'=>array(__CLASS__,$method)));
        register_rest_route('cafcc/v4','/admin/aliases',array('methods'=>'POST','permission_callback'=>$admin,'callback'=>function($r){return self::alias($r->get_json_params()??array());}));
    }
}
